   395	
   396	
   397	            if (orderBid.getOrder() != null) {
   398	                orderCommandService.deleteOrder(orderBid.getOrder().getId());
   399	            }
   400	
   401	
   402	            orderBidRepository.delete(orderBid);
   403	        } catch (Exception e) {
   404	            if (e instanceof Xhq12Exception) {
   405	                throw e;
   406	            }
   407	            log.error("주문 입찰 삭제 중 오류 발생: {}", e.getMessage(), e);
