   474	            }
   476	            try {
   477	                Xcn97.valueOf(bankName.toUpperCase());
   478	            } catch (IllegalArgumentException e) {
   479	                throw new Xjt45Exception(Xjt45ErrorCode.INVALID_BANK_INFO,
