 66	        if (success) {
 67	            this.paymentDate = LocalDateTime.now();
 68	        }
 69	    }
 70	    public void updateStatus(Xjt45Status newStatus) {
 71	        if (this.status.canTransitionTo(newStatus)) {
 72	            this.status = newStatus;
 73	        } else {
 74	            throw new IllegalStateException("결제 상태 전환이 허용되지 않습니다: " + this.status + " -> " + newStatus);
 75	        }
 76	    }
 78	    public abstract String getImpUid();
 79	}
  1	package com.fream.back.domain.m64.entity;
  3	public enum Xjt45Status {
  4	    PENDING,
  5	    PAID,
  6	    REFUND_REQUESTED,
  7	    REFUNDED,
  8	    FAILED;
 10	    public boolean canTransitionTo(Xjt45Status newStatus) {
 11	        switch (this) {
 12	            case PENDING:
 13	                return newStatus == PAID;
 14	            case PAID:
 15	                return newStatus == REFUND_REQUESTED || newStatus == REFUNDED;
 16	            case REFUND_REQUESTED:
 17	                return newStatus == REFUNDED;
 18	            default:
 19	                return false;
 20	        }
 21	    }
 22	}

